import{_ as l,a0 as d,w as u,s as a,I as n,x as t,a1 as o,A as e,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"迁移到 Linux：使用 sudo | LCTT x X-CMD","titleTemplate":false,"description":"迁移到 Linux：使用 sudo | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"迁移到 Linux：使用 sudo | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"迁移到 Linux：使用 sudo | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20180313 Migrating to Linux- Using Sudo","title":"迁移到 Linux：使用 sudo","tag":"201807","desc":""},"relativePath":"201807/20180313 Migrating to Linux- Using Sudo.md","filePath":"[post].md"}'),p={name:"201807/20180313 Migrating to Linux- Using Sudo.md"};function g(x,s,f,m,h,b){const i=d("Link");return u(),a("div",null,[s[22]||(s[22]=n("h1",{id:"迁移到-linux-使用-sudo",tabindex:"-1"},[t("迁移到 Linux：使用 sudo "),n("a",{class:"header-anchor",href:"#迁移到-linux-使用-sudo","aria-label":"Permalink to “迁移到 Linux：使用 sudo”"},"​")],-1)),s[23]||(s[23]=n("blockquote",null,[n("p",null,"sudo 机制可以让你轻松以普通用户偶尔执行管理任务。让我们来学习一下。")],-1)),s[24]||(s[24]=n("p",null,[n("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ray-hennessy-233438-unsplash.jpg?itok=d4l7QUtF",alt:""})],-1)),s[25]||(s[25]=n("p",null,"本文是我们关于迁移到 Linux 的系列文章的第五篇。如果你错过了之前的那些，你可以在这里赶上：",-1)),n("p",null,[o(i,{href:"https://linux.cn/article-9212-1.html"},{default:e(()=>[...s[0]||(s[0]=[t("第1部分 - 入门介绍",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9213-1.html"},{default:e(()=>[...s[1]||(s[1]=[t("第2部分 - 磁盘、文件和文件系统",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9293-1.html"},{default:e(()=>[...s[2]||(s[2]=[t("第3部分 - 图形操作环境",-1)])]),_:1}),o(i,{href:"https://linux.cn/article-9565-1.html"},{default:e(()=>[...s[3]||(s[3]=[t("第4部分 - 命令行",-1)])]),_:1})]),s[26]||(s[26]=r(`<p>你可能一直想了解 Linux。也许它在你的工作场所使用，如果你每天使用它，你的工作效率会更高。或者，也许你想在家里的某些计算机上安装 Linux。无论是什么原因，这一系列文章都是为了让过渡更容易。</p><p>与许多其他操作系统一样，Linux 支持多用户。它甚至支持多个用户同时登录。</p><p>用户帐户通常会被分配一个可以存储文件的家目录。通常这个家目​​录位于：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/home/&lt;login name&gt;</span></span></code></pre></div><p>这样，每个用户都有存储自己的文档和其他文件的独立位置。</p><h3 id="管理任务" tabindex="-1">管理任务 <a class="header-anchor" href="#管理任务" aria-label="Permalink to “管理任务”">​</a></h3><p>在传统的 Linux 安装中，常规用户帐户无权在系统上执行管理任务。典型的安装 Linux 的系统会要求用户以管理员身份登录以执行某些任务，而不是为每个用户分配权限以执行各种任务。</p><p>Linux 上的管理员帐户称为 root。</p><h3 id="sudo-解释" tabindex="-1">Sudo 解释 <a class="header-anchor" href="#sudo-解释" aria-label="Permalink to “Sudo 解释”">​</a></h3><p>从历史上看，要执行管理任务，必须以 root 身份登录，执行任务，然后登出。这个过程有点乏味，所以很多人以 root 登录并且整天都以管理员身份工作。这种做法可能会导致灾难性的后果，例如，意外删除系统中的所有文件。当然，root 用户可以做任何事情，因此没有任何保护措施可以防止有人意外地执行影响很大的操作。</p><p>创建 <code>sudo</code> 工具是为了使你更容易以常规用户帐户登录，偶尔以 root 身份执行管理任务，而无需登录、执行任务然后登出。具体来说，<code>sudo</code> 允许你以不同的用户身份运行命令。如果你未指定特定用户，则假定你指的是 root 用户。</p><p><code>sudo</code> 可以有复杂的设置，允许用户有权限使用 <code>sudo</code> 运行某些命令，而其他的不行。通常，安装的桌面系统会使创建的第一个帐户在 <code>sudo</code> 中有完全的权限，因此你作为主要用户可以完全管理 Linux 安装。</p><h3 id="使用-sudo" tabindex="-1">使用 Sudo <a class="header-anchor" href="#使用-sudo" aria-label="Permalink to “使用 Sudo”">​</a></h3><p>某些安装 Linux 的系统设置了 <code>sudo</code>，因此你仍需要知道 root 帐户的密码才能执行管理任务。其他人，设置 <code>sudo</code> 输入自己的密码。这里有不同的哲学。</p><p>当你尝试在图形环境中执行管理任务时，通常会打开一个要求输入密码的对话框。输入你自己的密码（例如，在 Ubuntu 上）或 root 帐户的密码（例如，Red Hat）。</p><p>当你尝试在命令行中执行管理任务时，它通常只会给你一个 “permission denied” 错误。然后你在前面用 <code>sudo</code> 重新运行命令。例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl start vsftpd</span></span>
<span class="line"><span>Failed to start vsftpd.service: Access denied</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo systemctl start vsftpd</span></span>
<span class="line"><span>[sudo] password for user1:</span></span></code></pre></div><h3 id="何时使用-sudo" tabindex="-1">何时使用 Sudo <a class="header-anchor" href="#何时使用-sudo" aria-label="Permalink to “何时使用 Sudo”">​</a></h3><p>以 root 身份运行命令（在 <code>sudo</code> 或其他情况下）并不总是解决权限错误的最佳解决方案。虽然将以 root 身份运行会消除 “permission denied” 错误，但有时最好寻找根本原因而不是仅仅解决症状。有时文件拥有错误的所有者和权限。</p><p>当你在尝试一个需要 root 权限来执行操作的任务或者程序时使用 <code>sudo</code>。如果文件恰好由另一个用户（包括 root 用户）拥有，请不要使用 <code>sudo</code>。在第二种情况下，最好正确设置文件的权限。</p>`,20)),n("p",null,[s[5]||(s[5]=t("通过 Linux 基金会和 edX 的免费",-1)),o(i,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:e(()=>[...s[4]||(s[4]=[t("“Linux 介绍”",-1)])]),_:1}),s[6]||(s[6]=t("课程了解有关 Linux 的更多信息。",-1))]),s[27]||(s[27]=n("hr",null,null,-1)),n("p",null,[s[8]||(s[8]=t("via: ",-1)),o(i,{href:"https://www.linux.com/blog/learn/2018/3/migrating-linux-using-sudo"},{default:e(()=>[...s[7]||(s[7]=[t("https://www.linux.com/blog/learn/2018/3/migrating-linux-using-sudo",-1)])]),_:1})]),n("p",null,[s[13]||(s[13]=t("作者：",-1)),o(i,{href:"https://www.linux.com/users/johnbonesio"},{default:e(()=>[...s[9]||(s[9]=[t("John Bonesio",-1)])]),_:1}),s[14]||(s[14]=t(" 选题：",-1)),o(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[10]||(s[10]=[t("lujun9972",-1)])]),_:1}),s[15]||(s[15]=t(" 译者：",-1)),o(i,{href:"https://github.com/geekpi"},{default:e(()=>[...s[11]||(s[11]=[t("geekpi",-1)])]),_:1}),s[16]||(s[16]=t(" 校对：",-1)),o(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[12]||(s[12]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[19]||(s[19]=t("本文由 ",-1)),o(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[17]||(s[17]=[t("LCTT",-1)])]),_:1}),s[20]||(s[20]=t(" 原创编译，",-1)),o(i,{href:"https://linux.cn/"},{default:e(()=>[...s[18]||(s[18]=[t("Linux中国",-1)])]),_:1}),s[21]||(s[21]=t(" 荣誉推出",-1))])])}const C=l(p,[["render",g]]);export{T as __pageData,C as default};
